package ai.docling.serve.api.util;

import static ai.docling.serve.api.util.ValidationUtils.ensureBetween;
import static ai.docling.serve.api.util.ValidationUtils.ensureEq;
import static ai.docling.serve.api.util.ValidationUtils.ensureGreaterThanZero;
import static ai.docling.serve.api.util.ValidationUtils.ensureNotNegative;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatExceptionOfType;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Duration;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullSource;
import org.junit.jupiter.params.provider.ValueSource;

class ValidationUtilsTests {
  @Test
    void ensure_eq() {
        ensureEq(1, 1, "test");
        ensureEq("abc", "abc", "test");
        ensureEq(null, null, "test");

        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> ensureEq(1, 2, "test %d", 7))
                .withMessageContaining("test 7");

        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> ensureEq(1, null, "test"))
                .withMessageContaining("test");
        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> ensureEq(null, 1, "test"))
                .withMessageContaining("test");
    }

    @Test
    void ensure_not_null() {
        {
            Object obj = new Object();
            assertThat(ValidationUtils.ensureNotNull(obj, "test")).isSameAs(obj);
        }

        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> ValidationUtils.ensureNotNull(null, "test"))
                .withMessage("test cannot be null");

        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> ValidationUtils.ensureNotNull(null, "test %d", 7))
                .withMessage("test 7");
    }

    @Test
    void ensure_not_empty_string() {
        {
            String str = " abc  ";
            assertThat(ValidationUtils.ensureNotEmpty(str, "test")).isSameAs(str);
        }

        {
            String str = "";
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty(str, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }

        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty((String) null, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }
    }

    @Test
    void ensure_not_empty_collection() {
        {
            List<Object> list = new ArrayList<>();
            list.add(new Object());
            assertThat(ValidationUtils.ensureNotEmpty(list, "test")).isSameAs(list);
        }

        {
            List<Object> list = new ArrayList<>();
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty(list, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }

        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty((Collection<?>) null, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }
    }

    @Test
    void ensure_not_empty_array() {
        {
            Object[] array = {new Object()};
            assertThat(ValidationUtils.ensureNotEmpty(array, "test")).isSameAs(array);
        }

        {
            Object[] array = {};
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty(array, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }

        {
            Object[] array = {};
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() ->
                            ValidationUtils.ensureNotEmpty(array, "%s", "Parameterized type has no type arguments."))
                    .withMessageContaining("Parameterized type has no type arguments.");
        }

        {
            Object[] array = null;
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty(array, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }
    }

    @Test
    void ensure_not_empty_map() {
        {
            Map<Object, Object> map = new HashMap<>();
            map.put(new Object(), new Object());
            assertThat(ValidationUtils.ensureNotEmpty(map, "test")).isSameAs(map);
        }

        {
            Map<Object, Object> map = new HashMap<>();
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty(map, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }

        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotEmpty((Map<?, ?>) null, "test"))
                    .withMessageContaining("test cannot be null or empty");
        }
    }

    @Test
    void ensure_not_blank() {
        {
            String str = " abc  ";
            assertThat(ValidationUtils.ensureNotBlank(str, "test")).isSameAs(str);
        }

        {
            String str = "  ";
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotBlank(str, "test"))
                    .withMessageContaining("test cannot be null or blank");
        }

        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureNotBlank(null, "test"))
                    .withMessageContaining("test cannot be null or blank");
        }
    }

    @Test
    void ensure_true() {
        {
            ValidationUtils.ensureTrue(true, "test");
        }

        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ValidationUtils.ensureTrue(false, "test"))
                    .withMessageContaining("test");
        }
    }

    @ParameterizedTest
    @ValueSource(ints = { 0, 1, Integer.MAX_VALUE})
    void should_not_throw_when_positive(Integer i) {
        ensureNotNegative(i, "integer");
    }

    @ParameterizedTest
    @NullSource
    @ValueSource(ints = {Integer.MIN_VALUE, -1})
    void should_throw_when_negative(Integer i) {
        assertThatThrownBy(() -> ensureNotNegative(i, "integer"))
                .isExactlyInstanceOf(IllegalArgumentException.class)
                .hasMessage("integer must not be negative, but is: " + i);
    }

    @ParameterizedTest
    @ValueSource(ints = {1, Integer.MAX_VALUE})
    void should_not_throw_when_greater_than_0(Integer i) {
        ensureGreaterThanZero(i, "integer");
    }

    @ParameterizedTest
    @NullSource
    @ValueSource(ints = {Integer.MIN_VALUE, 0})
    void should_throw_when_when_not_greater_than_0(Integer i) {
        assertThatThrownBy(() -> ensureGreaterThanZero(i, "integer"))
                .isExactlyInstanceOf(IllegalArgumentException.class)
                .hasMessage("integer must be greater than zero, but is: " + i);
    }

    @ParameterizedTest
    @ValueSource(doubles = {0.0, 0.5, 1.0})
    void should_not_throw_when_between(Double d) {
        ensureBetween(d, 0.0, 1.0, "test");
    }

    @ParameterizedTest
    @NullSource
    @ValueSource(doubles = {-0.1, 1.1})
    void should_throw_when_not_between(Double d) {
        assertThatThrownBy(() -> ensureBetween(d, 0.0, 1.0, "test"))
                .isExactlyInstanceOf(IllegalArgumentException.class)
                .hasMessage("test must be between 0.0 and 1.0, but is: " + d);
    }

    @Test
    void ensure_between_int() {
        {
            ensureBetween(1, 0, 1, "test");
        }
        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ensureBetween(2, 0, 1, "test"))
                    .withMessageContaining("test must be between 0 and 1, but is: 2");
        }
        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ensureBetween(-1, 0, 1, "test"))
                    .withMessageContaining("test must be between 0 and 1, but is: -1");
        }
    }

    @Test
    void ensure_between_long() {
        {
            ensureBetween(1L, 0, 1, "test");
        }
        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ensureBetween(2L, 0, 1, "test"))
                    .withMessageContaining("test must be between 0 and 1, but is: 2");
        }
        {
            assertThatExceptionOfType(IllegalArgumentException.class)
                    .isThrownBy(() -> ensureBetween(-1L, 0, 1, "test"))
                    .withMessageContaining("test must be between 0 and 1, but is: -1");
        }
    }

    @Test
    void ensurePositiveDuration() {
      ValidationUtils.ensurePositiveDuration(Duration.ofSeconds(1), "test");
      assertThatExceptionOfType(IllegalArgumentException.class)
          .isThrownBy(() -> ValidationUtils.ensurePositiveDuration(Duration.ofSeconds(-1), "test"))
          .withMessageContaining("test must be a positive duration");
      assertThatExceptionOfType(IllegalArgumentException.class)
          .isThrownBy(() -> ValidationUtils.ensurePositiveDuration(Duration.ofSeconds(0), "test"))
          .withMessageContaining("test must be a positive duration");
    }

}

"""
Ease documentation writing with mkdocs

- load the content of the 'variables.yaml' file
- provide the {{insert(file, tag)} macro

## Loading attributes

This feature loads a yaml file (default is `docs/attributes.yaml`), and import the content into the environment.
For example, if the imported file contains:

```
attributes:
  versions:
    camel: 3.13.0
    spec: 2.0.1
    mutiny: 1.1.2
  project-version: '3.14.0-SNAPSHOT'
  smallrye-config-version: '2.7.0'
```

You can access values using `{{ attributes.versions.camel}}` or `{{ attributes['project-version'] }}`.

The loaded file is `docs/variables.yaml` by default. The location can be configured in the `mkdocs.yml` file with:

```
extra:
  attributes_path: docs/my-attributes.yaml
```

## Partial file include

This feature allows including part of a file.
For example, include the code from the `Foo.java` located between `<example>` and `</example>`

```java linenums="1"
{{ insert('src/test/Foo.java', 'example') }}
```

The `Foo.java` file contain something like:

```
package test;

public class Foo {

    // <example> this is my snippet
    public static void main(String[]args){
        System.out.println("yoohoo");
    }
    // </example>

}
```

The file path is relative to the `docs` directory.
You can change the location using the `snippet_dir` attributes in the `mkdocs.yaml` file:

```
extra:
  snippet_dir: docs/snippets/src
```

Then, insert your snippet using:

```java linenums="1"
{{ insert('test/Foo.java', 'example') }}
```

When inserting you can:
- Pass a set of tags to skip - the content between the start and end tag will be excluded
- Hide a set of tags - //<tag> and //</tag> will be removed from the output

```java linenums="1"
{{ insert('test/Foo.java', 'example', [skip1, skip2], [hide1]) }}
```

"""

import math
import os.path
import textwrap
import yaml


def loadAttributes(env):
    path = env.conf['docs_dir'] + "/attributes.yaml"
    if 'attributes_path' in env.variables:
        path = env.variables['attributes_path']

    if os.path.exists(path):
        file = open(path)
        var = yaml.load(file, Loader=yaml.FullLoader)
        file.close()
        if var is not None:
            env.variables['attributes'] = var['attributes']
    else:
        print("Unable to import attributes - " + path  + " does not exists")

def areTagsInLine(line, tags):
    for tag in tags:
        if "<" + tag + ">" in line or "</" + tag + ">" in line:
            return True
    return False

def hasStartTagInLine(line, tags):
    for tag in tags:
        if "<" + tag + ">" in line:
            return True
    return False

def hasEndTagInLine(line, tags):
    for tag in tags:
        if "</" + tag + ">" in line:
            return True
    return False

def define_env(env):

    loadAttributes(env)

    @env.macro
    def insert(file, tag = None, skipTags = [], hideTags = []):
        root = env.conf['docs_dir']
        if 'snippet_dir' in env.variables:
           root = env.variables['snippet_dir']

        f = open(root + "/" + file)

        if tag is None:
            text = f.read()
            f.close()
            return textwrap.dedent(text)

        if tag is None:
            text = f.read()
            f.close()
            return textwrap.dedent(text)

        trace = False
        if "Hero.java" in file:
            trace = True

        if trace : print(f"Inserting {tag} from {file}")

        inRecordingMode = False
        inExclusionMode = False
        c = ""
        for line in f:
            if not inRecordingMode and not inExclusionMode:
                if "<" + tag + ">" in line:
                    inRecordingMode = True
            elif not inExclusionMode and "</" + tag + ">" in line:
                inRecordingMode = False
            elif inRecordingMode  and hasStartTagInLine(line, skipTags):
                inExclusionMode = True
            elif inExclusionMode  and hasEndTagInLine(line, skipTags):
                inExclusionMode = False
            elif inRecordingMode and not inExclusionMode:
                if not areTagsInLine(line, hideTags):
                       c += line

        f.close()
        if not c:
            raise Exception(f"Unable to find tag '{tag}' in '{file}'")

        c = textwrap.dedent(c)
        return c

    @env.macro
    def image(path, title):
        return f"""<figure class="docissimo, docissimo-figure">
              <img src="{path}" style="margin-left:auto; margin-right:auto;" alt="{title}">
              <figcaption style="margin-left:auto; margin-right:auto;">{title}</figcaption>
            </figure>"""

    @env.macro
    def javadoc(clazz, full = False, artifact = None):
        version = env.variables.attributes['project-version']
        if (artifact is None) :
            artifact = env.variables['javadoc_artifact']

        if not artifact:
            raise Exception("Missing configuration: 'extra.javadoc_artifact'")

        if not version:
            version = 'latest'

        path = clazz.replace(".", "/") + ".html"
        if full :
            name = clazz
        else :
            name = clazz.rsplit('.', 1)[1]
        return f"""<a class='docissimo, docissimo-javadoc' href='https://javadoc.io/doc/{artifact}/{version}/{path}'>{name}</a>"""

    @env.filter
    def reverse(x):
        "Reverse a string (and uppercase)"
        return x.upper()[::-1]

package ai.docling.serve.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatExceptionOfType;

import java.time.Duration;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;

import ai.docling.serve.api.TestApis.RecordingProvider;
import ai.docling.serve.api.spi.DoclingServeApiProvider.Unsupported;

class DoclingServeApiBuilderTests {
  @Test
  void providerReceivesTheConfiguration() {
    var provider = new RecordingProvider();
    var builder = DoclingServeApi.builder()
        .apiKey("key")
        .readTimeout(Duration.ofSeconds(7));

    var api = builder.build(provider);

    assertThat(provider.created())
        .singleElement()
        .isSameAs(api);
    assertThat(api.config()).isEqualTo(builder.config());
  }

  @Test
  void unsupportedOptionsLeftAtTheirDefaultAreNotEnforced() {
    var provider = new RecordingProvider(Map.of(DoclingServeApiConfig.ASYNC_EXECUTOR, Unsupported.FAIL));

    var api = DoclingServeApi.builder()
        .apiKey("key")
        .build(provider);

    assertThat(provider.created())
        .singleElement()
        .isSameAs(api);
  }

  @Test
  void ignoredOptionsDoNotPreventBuilding() {
    var provider = new RecordingProvider(Map.of(DoclingServeApiConfig.ASYNC_EXECUTOR, Unsupported.IGNORE));

    var api = DoclingServeApi.builder()
        .asyncExecutor(Runnable::run)
        .build(provider);

    assertThat(provider.created())
        .singleElement()
        .isSameAs(api);
    assertThat(api.config().asyncExecutor()).isNotNull();
  }

  @Test
  void warnedOptionsDoNotPreventBuilding() {
    var provider = new RecordingProvider(Map.of(DoclingServeApiConfig.ASYNC_EXECUTOR, Unsupported.WARN));

    var api = DoclingServeApi.builder()
        .asyncExecutor(Runnable::run)
        .build(provider);

    assertThat(provider.created())
        .singleElement()
        .isSameAs(api);
    assertThat(api.config().asyncExecutor()).isNotNull();
  }

  @Test
  void explicitlySetFailOptionsPreventBuildingAndNameEveryOptionInDeclarationOrder() {
    var provider = new RecordingProvider(Map.of(
        DoclingServeApiConfig.ASYNC_EXECUTOR, Unsupported.FAIL, DoclingServeApiConfig.LOG_REQUESTS, Unsupported.FAIL, DoclingServeApiConfig.PRETTY_PRINT, Unsupported.WARN));

    var builder = DoclingServeApi.builder()
        .asyncExecutor(Runnable::run)
        .prettyPrint()
        .logRequests();

    assertThatExceptionOfType(UnsupportedConfigurationException.class)
        .isThrownBy(() -> builder.build(provider))
        .withMessage(
            "The following options were explicitly configured but are not supported by %s: [logRequests, asyncExecutor]", RecordingProvider.class.getName())
        .satisfies(e -> assertThat(e)
            .returns(RecordingProvider.class.getName(), UnsupportedConfigurationException::getProvider)
            .extracting(UnsupportedConfigurationException::getUnsupportedOptions)
            .isEqualTo(List.of(DoclingServeApiConfig.LOG_REQUESTS, DoclingServeApiConfig.ASYNC_EXECUTOR)));

    assertThat(provider.created()).isEmpty();
  }
}

package ai.docling.serve.api;

import java.util.List;
import java.util.stream.Collectors;

/**
 * Thrown by {@link DoclingServeApiBuilder#build()} when the caller explicitly set options that the
 * resolved {@link ai.docling.serve.api.spi.DoclingServeApiProvider} declares as {@link ai.docling.serve.api.spi.DoclingServeApiProvider.Unsupported#FAIL}.
 */
public class UnsupportedConfigurationException extends IllegalArgumentException {
  private final String provider;
  private final List<ConfigOption<?>> unsupportedOptions;

  /**
   * Creates a new exception.
   *
   * @param provider           a description of the provider that does not support the options
   * @param unsupportedOptions the explicitly set options the provider does not support
   */
  public UnsupportedConfigurationException(String provider, List<ConfigOption<?>> unsupportedOptions) {
    super("The following options were explicitly configured but are not supported by %s: [%s]".formatted(
        provider, unsupportedOptions.stream()
            .map(ConfigOption::name)
            .collect(Collectors.joining(", "))));

    this.provider = provider;
    this.unsupportedOptions = List.copyOf(unsupportedOptions);
  }

  /**
   * A description of the provider that does not support the options.
   *
   * @return the provider description
   */
  public String getProvider() {
    return this.provider;
  }

  /**
   * The explicitly set options the provider does not support.
   *
   * @return an unmodifiable list of the unsupported options
   */
  public List<ConfigOption<?>> getUnsupportedOptions() {
    return this.unsupportedOptions;
  }
}

package ai.docling.serve.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalStateException;

import java.util.List;

import org.junit.jupiter.api.Test;

import ai.docling.serve.api.LegacyProviderAdapterTests.RecordingLegacyFactory;
import ai.docling.serve.api.TestApis.RecordingProvider;
import ai.docling.serve.api.spi.DoclingServeApiBuilderFactory;
import ai.docling.serve.api.spi.DoclingServeApiProvider;

@SuppressWarnings("removal")
class DoclingServeApiProvidersTests {
  @Test
  void singleProviderIsUsed() {
    var provider = new RecordingProvider();

    assertThat(DoclingServeApiProviders.resolve(List.of(provider), List.of())).isSameAs(provider);
  }

  @Test
  void singleLegacyFactoryIsAdapted() {
    var factory = new RecordingLegacyFactory();

    assertThat(DoclingServeApiProviders.resolve(List.of(), List.of(factory)))
        .isInstanceOf(LegacyProviderAdapter.class)
        .hasToString("%s (deprecated DoclingServeApiBuilderFactory)", RecordingLegacyFactory.class.getName());
  }

  @Test
  void providerIsPreferredOverLegacyFactory() {
    var provider = new RecordingProvider();

    assertThat(DoclingServeApiProviders.resolve(List.of(provider), List.of(new RecordingLegacyFactory()))).isSameAs(provider);
  }

  @Test
  void noneFound() {
    assertThatIllegalStateException()
        .isThrownBy(() -> DoclingServeApiProviders.resolve(List.of(), List.of()))
        .withMessage(
            "No instance of %s (or of the deprecated %s) found to build a %s instance. You are probably missing a library on your classpath.", DoclingServeApiProvider.class
                .getName(), DoclingServeApiBuilderFactory.class.getName(), DoclingServeApi.class.getName());
  }

  @Test
  void multipleProvidersFound() {
    assertThatIllegalStateException()
        .isThrownBy(() -> DoclingServeApiProviders.resolve(List.of(new RecordingProvider(), new OtherProvider()), List.of()))
        .withMessage(
            "Multiple instances of %s found to build a %s instance: [%s, %s]", DoclingServeApiProvider.class.getName(), DoclingServeApi.class.getName(), RecordingProvider.class
                .getName(), OtherProvider.class.getName());
  }

  @Test
  void multipleLegacyFactoriesFound() {
    assertThatIllegalStateException()
        .isThrownBy(() -> DoclingServeApiProviders.resolve(List.of(), List.of(new RecordingLegacyFactory(), new RecordingLegacyFactory())))
        .withMessageStartingWith("Multiple instances of %s found to build a %s instance: [", DoclingServeApiBuilderFactory.class.getName(), DoclingServeApi.class.getName())
        .withMessageContaining("%s (deprecated DoclingServeApiBuilderFactory)", RecordingLegacyFactory.class.getName());
  }

  private static final class OtherProvider implements DoclingServeApiProvider {
    @Override
    public DoclingServeApi create(DoclingServeApiConfig config) {
      return new TestApis.StubDoclingServeApi(config);
    }
  }
}

